python3 - <<'EOF'
import json, glob

total = 0
for path in sorted(glob.glob('data/*.jsonl')):
    with open(path) as f:
        for line in f:
            rec = json.loads(line)
            if rec.get('kind') != 'span':
                continue
            span = rec.get('body', {}).get('span', {})
            el = span.get('elapsed')
            if el is None:
                continue
            v, u = el['value'], el['unit']
            if u == 'ms':
                total += v
            elif u == 'us':
                total += v // 1000
            elif u == 's':
                total += v * 1000
            else:
                raise ValueError(u)
print(total)
EOF
